const targetTotal = 2100;
const finalCorpus = [];

WORDS_DATA.forEach(([w, pos, th, en, cat, mana]) => {
  finalCorpus.push({
    word: w,
    pos: pos || 'v.',
    meaningTh: th,
    exampleEn: en,
    category: cat || 'Corporate',
    manaCost: mana || 3,
  });
});

// เสริมคำศัพท์ทางธุรกิจขั้นสูงที่มีรากศัพท์และตระกูลคำ (Word Family) อีก 1,500+ คำ
const ADVANCED_STEMS = require('./advanced-business-stems.json');
ADVANCED_STEMS.forEach((card) => {
  finalCorpus.push(card);
});

console.log(`Total corpus items: ${finalCorpus.length}`);
fs.writeFileSync(path.join(__dirname, 'toeic-vocab-corpus.json'), JSON.stringify(finalCorpus, null, 2), 'utf8');
